#[test]
fn hierarchy() -> Result<()> {
    let h = recap_decompose(&mol_from_smiles("C1CC1Oc1ccccc1-c1ncc(OC)cc1")?)?;
    let root = h.root().unwrap();
    let all = root.get_all_children();
    let node = all.iter().find(|(s, _)| *s == "*C1CC1").unwrap().1;
    assert_eq!(
        keys(&node.parents()),
        vec!["COc1ccc(-c2ccccc2OC2CC2)nc1", "*c1ccccc1OC1CC1"]
    );
    assert_eq!(node.get_ultimate_parents(), [root]);
    assert_eq!(mol_to_smiles(node.mol())?, "*C1CC1");
    let node = all
        .iter()
        .find(|(s, _)| *s == "*c1ccccc1-c1ccc(OC)cn1")
        .unwrap()
        .1;
    assert_eq!(keys(&node.parents()), vec!["COc1ccc(-c2ccccc2OC2CC2)nc1"]);
    assert_eq!(node.get_ultimate_parents(), [root]);
    assert_eq!(mol_to_smiles(node.mol())?, "*c1ccccc1-c1ccc(OC)cn1");
    let node = all.iter().find(|(s, _)| *s == "*c1ccccc1*").unwrap().1;
    assert_eq!(
        keys(&node.parents()),
        vec!["*c1ccccc1-c1ccc(OC)cn1", "*c1ccccc1OC1CC1"]
    );
    assert_eq!(node.get_ultimate_parents(), [root]);
    assert_eq!(mol_to_smiles(node.mol())?, "*c1ccccc1*");
    let node = all.iter().find(|(s, _)| *s == "*c1ccc(OC)cn1").unwrap().1;
    assert_eq!(
        keys(&node.parents()),
        vec!["COc1ccc(-c2ccccc2OC2CC2)nc1", "*c1ccccc1-c1ccc(OC)cn1"]
    );
    assert_eq!(node.get_ultimate_parents(), [root]);
    assert_eq!(mol_to_smiles(node.mol())?, "*c1ccc(OC)cn1");
    let node = all.iter().find(|(s, _)| *s == "*c1ccccc1OC1CC1").unwrap().1;
    assert_eq!(keys(&node.parents()), vec!["COc1ccc(-c2ccccc2OC2CC2)nc1"]);
    assert_eq!(node.get_ultimate_parents(), [root]);
    assert_eq!(mol_to_smiles(node.mol())?, "*c1ccccc1OC1CC1");
    assert_eq!(root.get_ultimate_parents(), [root]);
    assert_eq!(h.len(), 6);
    Ok(())
}

#[test]
fn shared_nodes() -> Result<()> {
    let mut h = RecapHierarchy::new();
    let root = h.recap_decompose(
        &mol_from_smiles("c1ccccc1-c1ncccc1")?,
        &RecapDecomposeParams::default(),
    )?;
    assert_eq!(keys(&root.children()), vec!["*c1ccccc1", "*c1ccccn1"]);
    assert_eq!(keys(&root.get_leaves()), vec!["*c1ccccc1", "*c1ccccn1"]);
    assert_eq!(
        h.keys(),
        vec!["c1ccc(-c2ccccn2)cc1", "*c1ccccc1", "*c1ccccn1"]
    );
    let root = h.recap_decompose(
        &mol_from_smiles("COc1ccccc1-c1ncccc1")?,
        &RecapDecomposeParams::default(),
    )?;
    assert_eq!(keys(&root.children()), vec!["*c1ccccn1", "*c1ccccc1OC"]);
    assert_eq!(keys(&root.get_leaves()), vec!["*c1ccccn1", "*c1ccccc1OC"]);
    assert_eq!(
        h.keys(),
        vec![
            "c1ccc(-c2ccccn2)cc1",
            "*c1ccccc1",
            "*c1ccccn1",
            "COc1ccccc1-c1ccccn1",
            "*c1ccccc1OC"
        ]
    );
    let root = h.recap_decompose(
        &mol_from_smiles("C1CC1Oc1ccccc1-c1ncccc1")?,
        &RecapDecomposeParams::default(),
    )?;
    assert_eq!(
        keys(&root.children()),
        vec![
            "*C1CC1",
            "*c1ccccc1-c1ccccn1",
            "*c1ccccn1",
            "*c1ccccc1OC1CC1"
        ]
    );
    assert_eq!(
        keys(&root.get_leaves()),
        vec!["*C1CC1", "*c1ccccn1", "*c1ccccc1*"]
    );
    assert_eq!(
        h.keys(),
        vec![
            "c1ccc(-c2ccccn2)cc1",
            "*c1ccccc1",
            "*c1ccccn1",
            "COc1ccccc1-c1ccccn1",
            "*c1ccccc1OC",
            "c1ccc(-c2ccccc2OC2CC2)nc1",
            "*C1CC1",
            "*c1ccccc1-c1ccccn1",
            "*c1ccccc1OC1CC1",
            "*c1ccccc1*"
        ]
    );
    let root = h.recap_decompose(
        &mol_from_smiles("COc1ccccc1-c1ncccc1")?,
        &RecapDecomposeParams::default(),
    )?;
    assert_eq!(keys(&root.children()), vec!["*c1ccccn1", "*c1ccccc1OC"]);
    assert_eq!(keys(&root.get_leaves()), vec!["*c1ccccn1", "*c1ccccc1OC"]);
    assert_eq!(
        h.keys(),
        vec![
            "c1ccc(-c2ccccn2)cc1",
            "*c1ccccc1",
            "*c1ccccn1",
            "COc1ccccc1-c1ccccn1",
            "*c1ccccc1OC",
            "c1ccc(-c2ccccc2OC2CC2)nc1",
            "*C1CC1",
            "*c1ccccc1-c1ccccn1",
            "*c1ccccc1OC1CC1",
            "*c1ccccc1*"
        ]
    );
    let node = h.get("*c1ccccc1").unwrap();
    assert_eq!(keys(&node.parents()), vec!["c1ccc(-c2ccccn2)cc1"]);
    let ultimate: Vec<&str> = node
        .get_ultimate_parents()
        .iter()
        .map(|n| n.smiles())
        .collect();
    assert_eq!(ultimate, vec!["c1ccc(-c2ccccn2)cc1"]);
    assert!(h.get("CCCC").is_none());
    Ok(())
}

#[test]
fn reactions_parse() -> Result<()> {
    assert_eq!(reaction_defs().len(), 12);
    assert_eq!(
        reaction_to_smarts(&reactions()[3])?,
        r"[N&!D1&+0&!$(N-C=[#7,#8,#15,#16])](-&!@[*:1])-&!@[*:2]>>*[*:1].[*:2]*"
    );
    Ok(())
}
